  'chat.designToolbox.prompt.contextGeneric': 'Ge├ºerli hedef: ┼ƒu anda a├º─▒k olan HTML / tasar─▒m dosyas─▒ / web ├╢─ƒesi.',
  'chat.designToolbox.prompt.contextSpecific': 'Ge├ºerli hedef: {kind} ┬╖ {label}.',
