  'chat.designToolbox.prompt.selectedSkill': 'Se├ºili skill: {skill}. Bu turda birincil i┼ƒ ak─▒┼ƒ─▒ olarak kullan.',
  'chat.designToolbox.prompt.noSkill': 'Belirli bir skill e┼ƒle┼ƒmediyse, ├╢nce mevcut skill\'ler, MCP, plugin\'ler, connector\'lar ve tasar─▒m dosyalar─▒ndan en iyi kombinasyonu se├º.',
  'chat.designToolbox.prompt.autoMatchIntro': 'Creative Director orkestrat├╢r├╝ olarak hareket et ve bir tasar─▒m i┼ƒ ak─▒┼ƒ─▒n─▒ tamamla:',
  'chat.designToolbox.prompt.autoMatchStep1': '1. ├ûnce "iyi g├╢r├╝nen tasar─▒m"─▒n ne anlama geldi─ƒini tan─▒mlay─▒n: hedef kitle, i┼ƒ hedefi, marka hissi, stil referanslar─▒, bilgi yo─ƒunlu─ƒu, renk/tipografi/hareket/varl─▒k standartlar─▒ ve ka├º─▒n─▒lmas─▒ gereken AI/┼ƒablon kal─▒plar─▒.',
  'chat.designToolbox.prompt.autoMatchStep2': '2. Yukar─▒daki tam kaynak dizinini ara ve e┼ƒle┼ƒtir. Yaln─▒zca tasar─▒m ara├º kutusu ├╢nerilerini kullanma; faydal─▒ oldu─ƒunda skill\'leri, MCP\'yi, plugin\'leri, connector\'lar─▒ ve tasar─▒m dosyalar─▒n─▒ birle┼ƒtir.',
  'chat.designToolbox.prompt.autoMatchStep3': '3. Hedef veya estetik ├º─▒ta h├ól├ó belirsizse, bana sonlu se├ºeneklerle veya form tarz─▒ bir aray├╝zle rehberlik et ve ├╢nerilen bir varsay─▒lan ekle. Yeterince netse, sonraki ad─▒m─▒ do─ƒrudan y├╝r├╝t.',
  'chat.designToolbox.prompt.autoMatchStep4': '4. Ak─▒┼ƒ─▒ ┼ƒu s─▒rayla tamamla: te┼ƒhis -> stil y├╢n├╝ -> kaynak se├ºimi -> somut d├╝zenleme/olu┼ƒturma -> do─ƒrulama. Her ad─▒mda, bu kaynaklar─▒n neden se├ºildi─ƒini ve s─▒rada neyin onaylanmas─▒ gerekti─ƒini a├º─▒kla.',
  'chat.designToolbox.prompt.motion': 'Ge├ºerli HTML / sayfa ├╢─ƒesine y├╝ksek kaliteli hareket ekle: en faydal─▒ 1-2 giri┼ƒ, kayd─▒rma, durum ge├ºi┼ƒi veya mikro etkile┼ƒim an─▒n─▒ se├º. ├ûl├º├╝l├╝ tut, transform / opacity tercih et ve prefers-reduced-motion geri d├╢n├╝┼ƒlerini ekle.',
  'chat.designToolbox.prompt.motionPolish': 'Mevcut hareketin zamanlamas─▒n─▒, yumu┼ƒatmas─▒n─▒, performans─▒n─▒ ve eri┼ƒilebilirli─ƒini incele ve cilala. Ani, ucuz veya okunabilirli─ƒe zarar veren animasyonu kald─▒r; gerekti─ƒinde daha rafine bir zaman ├ºizelgesi kullan.',
  'chat.designToolbox.prompt.antiAiPolish': 'Yapay zeka hissine kar┼ƒ─▒ bir cilalama turu yap: ┼ƒablonla┼ƒm─▒┼ƒ d├╝zenleri, ucuz gradyanlar─▒/par─▒lt─▒lar─▒, anlams─▒z kart y─▒─ƒ─▒nlar─▒n─▒ ve belirsiz metni kald─▒r. Bilgiyi koru ve ger├ºek bir tasar─▒mc─▒n─▒n teslim etti─ƒi hissini ver.',
  'chat.designToolbox.prompt.visualPolish': 'Bu tasar─▒m─▒ yay─▒na haz─▒r olana kadar cilala: hiyerar┼ƒiyi, tipografiyi, bo┼ƒluklar─▒, duyarl─▒ davran─▒┼ƒ─▒, buton durumlar─▒n─▒, bo┼ƒ/y├╝kleniyor/hata durumlar─▒n─▒ ve eri┼ƒilebilirli─ƒi kontrol et; en ├╢nemli sorunlar─▒ do─ƒrudan d├╝zelt.',
  'chat.designToolbox.prompt.imageGen': 'Bu tasar─▒m i├ºin bir sonraki g├╢rsel varl─▒k plan─▒n─▒ olu┼ƒtur: b├╢l├╝m referanslar─▒, hero varl─▒klar─▒, ill├╝strasyonlar, ikonlar, sosyal g├╢rseller veya bir ilham panosu. ├ûnce hangi t├╝r g├╢rselin eksik oldu─ƒuna karar ver, ard─▒ndan y├╝r├╝t├╝lebilir olu┼ƒturma prompt\'lar─▒ / dosya plan─▒ sa─ƒla.',
  'chat.designToolbox.prompt.videoGen': 'Bu tasar─▒m─▒ videoya y├╢nlendir: k─▒sa video storyboard\'u, Hyperframes / Remotion kare yap─▒s─▒ veya Sora/fal\'a haz─▒r bir prompt olu┼ƒtur. Mevcut HTML / sayfa i├ºeri─ƒinin do─ƒal olarak ├ºekimlere d├╢n├╝┼ƒmesini tercih et.',
  'chat.designToolbox.prompt.useSkill': 'Ge├ºerli tasar─▒mda {skill} kullan.',
  'chat.designToolbox.prompt.skillInstruction': '├ûnce en iyi takip hedefine karar ver, ard─▒ndan somut bir tur tamamla. Harici varl─▒klara veya API\'lere ba─ƒl─▒ysa, ├ºal─▒┼ƒt─▒r─▒labilir bir geri d├╢n├╝┼ƒ sa─ƒla ya da neyi sa─ƒlamam gerekti─ƒini belirt.',
