  'chat.designToolbox.prompt.resourceDescription': 'Kaynak a├º─▒klamas─▒: {description}',
  'chat.designToolbox.prompt.pluginResource': 'Bu plugin\'i ge├ºerli tasar─▒m ak─▒┼ƒ─▒ i├ºin ana ba─ƒlam olarak kullan. Girdiler veya GenUI a├º─▒─ƒa ├º─▒kar─▒yorsa, gerekti─ƒinde se├ºim yapmam i├ºin bana rehberlik et; hedefe uymuyorsa, daha iyi bir global kaynak se├º ve nedenini a├º─▒kla.',
  'chat.designToolbox.prompt.mcpResource': 'Sonraki tasar─▒m ad─▒m─▒ i├ºin bu MCP yetene─ƒini tercih et. Harici varl─▒klar, web yakalama, g├╢rsel/video olu┼ƒturma veya veri gerekti─ƒinde, ├╢nce i┼ƒi yap─▒p yapamayaca─ƒ─▒na karar ver, ard─▒ndan y├╝r├╝t├╝lebilir bir plan sun.',
  'chat.designToolbox.prompt.mcpTemplateResource': 'Bu MCP yap─▒land─▒r─▒labilir bir ┼ƒablondur. Bu tasar─▒m ad─▒m─▒ i├ºin en faydal─▒ ara├ºsa, ├╢nce kuruluma rehberlik et; yap─▒land─▒r─▒lm─▒┼ƒ bir alternatif varsa, o alternatifle devam et.',
  'chat.designToolbox.prompt.connectorResource': 'Ger├ºek veri, varl─▒k, hesap i├ºeri─ƒi veya harici i┼ƒ ak─▒┼ƒ─▒ eri┼ƒimi gerekti─ƒinde bu connector\'─▒ kullan. Kullanmadan ├╢nce, neyin okunaca─ƒ─▒n─▒ veya yaz─▒laca─ƒ─▒n─▒ a├º─▒kla ve uygun oldu─ƒunda onay iste.',
