  'chat.example1Prompt': '10 slaytl─▒k bir editoryal pitch deck: seed yat─▒r─▒m turu i├ºin fon arayan bir tasar─▒m st├╝dyosu ΓÇö ─░svi├ºre grid yerle┼ƒimi, b├╝y├╝k serif ba┼ƒl─▒klar ve kal─▒n drop capΓÇÖler, monospace b├╢l├╝m numaralar─▒, geni┼ƒ negatif alan kullan─▒m─▒ ve metin yo─ƒun slaytlarla d├╢n├╝┼ƒ├╝ml├╝ tam sayfa (full-bleed) foto─ƒraf slaytlar─▒. Kapak, vizyon, pazar, ├╝r├╝n, traction, ekip, talep, ileti┼ƒim.',
  'chat.example2Title': 'SaaS analitik g├╢sterge paneli',
