  'chat.example2Prompt': 'Geli┼ƒtirici ara├ºlar─▒na y├╢nelik bir SaaS i├ºin yo─ƒun bir analitik g├╢sterge paneli: haftadan haftaya de─ƒi┼ƒimleri g├╢steren KPI ┼ƒeridi, ├╝st ├╝ste yerle┼ƒtirilmi┼ƒ iki ├ºizgi grafik (MRR ve aktif ├ºal─▒┼ƒma alanlar─▒), kullan─▒m─▒n d├╝nya ─▒s─▒ haritas─▒, cohort retention gridΓÇÖi, en iyi m├╝┼ƒteriler liderlik tablosu ve ger├ºek zamanl─▒ olay ak─▒┼ƒ─▒. Karanl─▒k tema, tabular monospace rakamlar, sparkline vurgular─▒.',
